<#
  NUDGE Figma design system: docs generator.

  Reads  ../../02-Design-Variables/Figma-Variables/variable-map.json (GENERATED) and components.json (SOURCE) and WRITES, in this folder only:
    components.md             component specifications (generated from components.json)
    component-properties.md   one table of every component property (generated)
    typography-styles.md      the 21 Text Styles (generated from variable-map.json)
    Preview/preview-data.js   the data file the browser preview reads (generated). The preview contains no values of its own.
  Run build-figma-variables.ps1 first, then this script.
  Run:  powershell -ExecutionPolicy Bypass -File 01-Design-System/Figma-Specification/build-figma-docs.ps1
#>
$ErrorActionPreference = 'Stop'
$here = $PSScriptRoot
$proj = Split-Path -Parent (Split-Path -Parent $here)   # project root
$fv = Join-Path $proj '02-Design-Variables/Figma-Variables'
$enc = New-Object Text.UTF8Encoding($false)
$nl = "`n"
$map = Get-Content (Join-Path $fv 'variable-map.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$comp = Get-Content (Join-Path $here 'components.json') -Raw -Encoding UTF8 | ConvertFrom-Json
function Esc([string]$s) { ($s -replace '\|', '\|') }

# ---------- typography-styles.md ----------
$t = New-Object Text.StringBuilder
[void]$t.Append("<!-- GENERATED by build-figma-docs.ps1 from 02-Design-Variables/Figma-Variables/variable-map.json. DO NOT EDIT BY HAND. -->$nl# Typography styles (Figma)$nl$nl")
[void]$t.Append("**Canonical units: px.** Every font size in this specification is a pixel number. No value is in points (``pt``), and the validator fails on any point unit (check 6).$nl$nl")
[void]$t.Append("## Variables, Text Styles and what binds to what$nl$nl| | Figma Variable | Figma Text Style |$nl|---|---|---|$nl")
[void]$t.Append("| What it is | One named value of one type (colour, number, text, true/false), with one value per mode | A saved bundle of text properties applied to a text layer |$nl")
[void]$t.Append("| Holds here | font family names, font weights, **font sizes in px** (per tier mode) | the bundle: family, weight, size, **line height %**, **letter spacing %**, case |$nl")
[void]$t.Append("| Modes | Yes (font sizes have Mobile, Tablet, Desktop) | No. A style appears once; its size follows the mode when the size is bound to a variable (to verify in Figma) |$nl")
[void]$t.Append("| Why not only variables | Line height and letter spacing are unitless ratios and em values on the web; Figma stores them per style as a percentage or px value, and binding a px variable to a ratio needs a per-style conversion | Why not only styles: the sizes must change by tier and stay linked to the web values |$nl$nl")
[void]$t.Append("**How they work together.** The style's family, weight and size are *bound* to variables (``font/family/*``, ``font/weight/*``, ``font-size/*``). Line height and letter spacing are stored in the style as percentages. Designers apply the style; the tier is chosen by setting the **Typography** mode on the frame.$nl$nl")
[void]$t.Append("## Display versus storage in Figma$nl$nl- **Size** is stored and shown as px. Fluid web sizes are sampled at 360, 768 and 1280px and rounded to a whole px (deviation from the web value at those widths: at most 0.5px; between them the web size is continuous and Figma is not).$nl- **Weight** is stored as a number (400, 500, 600, 700) in the variable, but Figma applies a font **style name**: 400 Regular, 500 Medium, 600 SemiBold, 700 Bold. Confirm that the installed font exposes those style names (Cormorant ships static weights; DM Sans is a variable family).$nl- **Line height** is specified in percent (the web ratio x 100). The px equivalents below are what Figma computes (size x percent).$nl- **Letter spacing** is specified in percent (the web em value x 100); the px equivalent below is for the Desktop size.$nl- **Case**: ``UPPER`` is Figma's text case setting, the equivalent of ``text-transform: uppercase``.$nl- **Font stack**: the web system lists fallback fonts; Figma has none, so the primary family only is used.$nl$nl")
[void]$t.Append("## The $(@($map.textStyles).Count) Text Styles$nl$nl| Style | Web role | Family | Weight | Size px (Mobile / Tablet / Desktop) | Line height | Line height px (Mobile / Desktop) | Letter spacing | Case | Bound variables | Use |$nl|---|---|---|---|---|---|---|---|---|---|---|$nl")
foreach ($s in $map.textStyles) {
  $m = [double]$s.fontSizePx.Mobile; $d = [double]$s.fontSizePx.Desktop
  $lhM = [math]::Round($m * $s.lineHeightPercent / 100, 1); $lhD = [math]::Round($d * $s.lineHeightPercent / 100, 1)
  [void]$t.Append("| ``$($s.name)`` | $($s.webRole) | $($s.fontFamily) | $($s.fontWeight) | $($s.fontSizePx.Mobile) / $($s.fontSizePx.Tablet) / $($s.fontSizePx.Desktop) | $($s.lineHeightPercent)% | $lhM / $lhD | $($s.letterSpacingPercent)% ($([math]::Round($d * $s.letterSpacingPercent / 100, 2)) px) | $($s.textCase) | ``$($s.fontFamilyVariable)``, ``$($s.fontWeightVariable)``, ``$($s.fontSizeVariable)`` | $(Esc $s.usage) |$nl")
}
[void]$t.Append("$nl## Setting up the styles in Figma (manual; nothing here was created in Figma)$nl$nl1. Create the variables first (see [../../02-Design-Variables/Figma-Variables/README.md](../../02-Design-Variables/Figma-Variables/README.md)).$nl2. Create one Text Style per row, named exactly as in the table (the slash creates the folder).$nl3. In each style bind **font family**, **font weight** (or choose the matching style name) and **font size** to the named variables; type the line height and letter spacing percentages.$nl4. Set the frame's **Typography** mode to Mobile, Tablet or Desktop and check that the sizes in the preview match the table.$nl")
[IO.File]::WriteAllText((Join-Path $here 'typography-styles.md'), $t.ToString(), $enc)

# ---------- components.md and component-properties.md ----------
$c = New-Object Text.StringBuilder
[void]$c.Append("<!-- GENERATED by build-figma-docs.ps1 from components.json. DO NOT EDIT BY HAND. -->$nl# Figma components$nl$nl")
[void]$c.Append("$(@($comp.components).Count) components selected from the web Design System for genuine reuse, plus $(@($comp.patterns).Count) patterns. This is a **specification**: no component was created in Figma. Every variable named below exists in [../../02-Design-Variables/Figma-Variables/collections.md](../../02-Design-Variables/Figma-Variables/collections.md) (validated).$nl$nl")
[void]$c.Append("| Component | Web equivalent | Priority | Variant properties | Variants | Booleans | Text | Instance swaps |$nl|---|---|---|---|---|---|---|---|$nl")
foreach ($x in $comp.components) {
  $vp = @($x.properties | Where-Object { $_.type -eq 'VARIANT' }); $n = 1; foreach ($p in $vp) { $n *= @($p.values).Count }
  [void]$c.Append("| [$($x.name)](#$($x.id)) | ``$(Esc $x.webComponent)`` | $($x.priority) | $(($vp | ForEach-Object { $_.name }) -join ', ') | $n | $(@($x.properties | Where-Object { $_.type -eq 'BOOLEAN' }).Count) | $(@($x.properties | Where-Object { $_.type -eq 'TEXT' }).Count) | $(@($x.properties | Where-Object { $_.type -eq 'INSTANCE_SWAP' }).Count) |$nl")
}
[void]$c.Append("$nl**Naming and conventions.** Component names are Title Case; variant property names and values are Title Case (``State = Hover``); booleans start with ``Show`` or describe a toggle (``Removable``, ``Sold out``); text properties are nouns (``Label``, ``Title``). State is a **variant** because states change fills and strokes; optional parts are **booleans** because they only show or hide layers; swappable content (icons, images, slots) is an **instance swap**; copy is a **text** property.$nl$nl**Icons.** $($comp.iconNote) Icons: $(($comp.icons) -join ', ').$nl$nl")
foreach ($x in $comp.components) {
  [void]$c.Append("---$nl$nl## $($x.name)  <a id=`"$($x.id)`"></a>$nl$nl$($x.summary)$nl$nl- **Web equivalent:** ``$(Esc $x.webComponent)``$nl- **Text style:** $($x.textStyle)$nl- **Variants:** $($x.variantNote)$nl$nl")
  [void]$c.Append("**Properties**$nl$nl| Property | Type | Values | Default | Note |$nl|---|---|---|---|---|$nl")
  foreach ($p in $x.properties) { [void]$c.Append("| $($p.name) | $($p.type) | $((@($p.values) -join ', ')) | $(Esc ([string]$p.default)) | $(Esc $p.note) |$nl") }
  [void]$c.Append("$nl**Auto Layout**$nl$nl| Aspect | Specification |$nl|---|---|$nl| Direction | $($x.layout.direction) |$nl| Width | $($x.layout.widthSizing) |$nl| Height | $($x.layout.heightSizing) |$nl| Padding | $($x.layout.padding) |$nl| Gap | $($x.layout.gap) |$nl| Alignment | $($x.layout.align) |$nl")
  if ($x.layout.minWidth) { [void]$c.Append("| Minimum width | $($x.layout.minWidth) |$nl") }
  [void]$c.Append("$nl**Variable bindings**$nl$nl| Element | Property | Variable |$nl|---|---|---|$nl")
  foreach ($b in $x.bindings) { [void]$c.Append("| $($b.element) | $($b.property) | ``$($b.variable)`` |$nl") }
  if (@($x.stateStyles).Count -gt 1) {
    [void]$c.Append("$nl**State styles** (variable bound to each state)$nl$nl| Variant | State | Fill | Stroke | Stroke width | Text | Focus ring | Stroke style |$nl|---|---|---|---|---|---|---|---|$nl")
    foreach ($s in $x.stateStyles) { $vv = ($s.variant.PSObject.Properties | ForEach-Object { "$($_.Name)=$($_.Value)" }) -join ', '; [void]$c.Append("| $vv | $($s.state) | $(if ($s.fill) { '`' + $s.fill + '`' } else { 'none' }) | $(if ($s.stroke) { '`' + $s.stroke + '`' } else { 'none' }) | $(if ($s.strokeWidth) { '`' + $s.strokeWidth + '`' } else { '' }) | $(if ($s.text) { '`' + $s.text + '`' } else { '' }) | $(if ($s.focusRing) { 'yes' } else { '' }) | $($s.strokeStyle) |$nl") }
  }
  [void]$c.Append("$nl**Responsive intent.** $($x.responsive)$nl$nl**Accessibility.** $($x.accessibility)$nl$nl**Developer handoff.** $($x.handoff)$nl$nl")
  if (@($x.notRepresentedInFigma).Count) { [void]$c.Append("**Not representable in Figma:** $((@($x.notRepresentedInFigma)) -join '; ').$nl$nl") }
}
[void]$c.Append("---$nl$nl## Patterns$nl$nl| Pattern | Built from | Note |$nl|---|---|---|$nl")
foreach ($p in $comp.patterns) { [void]$c.Append("| $($p.name) | $((@($p.uses)) -join ', ') | $($p.note) |$nl") }
[void]$c.Append("$nl## Deliberately not components$nl$nl"); foreach ($n in $comp.notComponents) { [void]$c.Append("- $n$nl") }
[IO.File]::WriteAllText((Join-Path $here 'components.md'), $c.ToString(), $enc)

$q = New-Object Text.StringBuilder
[void]$q.Append("<!-- GENERATED by build-figma-docs.ps1 from components.json. DO NOT EDIT BY HAND. -->$nl# Component properties$nl$nl")
[void]$q.Append("Figma component property types: **VARIANT** (a choice that changes the look, stored as a variant set), **BOOLEAN** (show or hide a layer), **TEXT** (editable copy), **INSTANCE_SWAP** (replace a nested instance). Variables, Styles and component properties are three different mechanisms: a Variable holds a value, a Style bundles text or effect settings, and a property exposes a choice on one component (see the preview).$nl$nl| Component | Property | Type | Values | Default | Note |$nl|---|---|---|---|---|---|$nl")
foreach ($x in $comp.components) { foreach ($p in $x.properties) { [void]$q.Append("| $($x.name) | $($p.name) | $($p.type) | $((@($p.values) -join ', ')) | $(Esc ([string]$p.default)) | $(Esc $p.note) |$nl") } }
[IO.File]::WriteAllText((Join-Path $here 'component-properties.md'), $q.ToString(), $enc)

# ---------- Preview/preview-data.js ----------
$srcHashes = [ordered]@{}
foreach ($sf in 'collections.source.json', 'primitives.json', 'spacing.json', 'typography.json', 'semantic.json', 'layout.json', 'component-variables.json') { $srcHashes["02-Design-Variables/Figma-Variables/$sf"] = (Get-FileHash (Join-Path $fv $sf)).Hash }
$srcHashes['01-Design-System/Figma-Specification/components.json'] = (Get-FileHash (Join-Path $here 'components.json')).Hash
$pvVars = @($map.variables | ForEach-Object { [ordered]@{ name = $_.name; collection = $_.collection; type = $_.type; layer = $_.layer; description = $_.description; webToken = $_.webToken; webRelation = $_.webRelation; webRaw = $_.webRaw; webResolved = $_.webResolved; scopes = @($_.scopes); sourceFile = $_.sourceFile; hidden = $_.hiddenFromPublishing; values = $_.values } })
$spec = [ordered]@{
  meta = [ordered]@{ note = 'GENERATED by build-figma-docs.ps1. This is a preview of a PROPOSED Figma specification, not a Figma file. DO NOT EDIT BY HAND.'; variableMapSha256 = (Get-FileHash (Join-Path $fv 'variable-map.json')).Hash; componentsSha256 = (Get-FileHash (Join-Path $here 'components.json')).Hash; counts = $map.meta.counts; sourceHashes = $srcHashes }
  collections = $map.collections
  variables = $pvVars
  textStyles = $map.textStyles
  gridStyles = $map.gridStyles
  effectStyles = $map.effectStyles
  components = $comp.components
  patterns = $comp.patterns
  icons = $comp.icons
  iconNote = $comp.iconNote
  provisionalDecisions = $comp.provisionalDecisions
  pendingItems = $comp.pendingItems
  notComponents = $comp.notComponents
  webMapping = $map.webMapping
  mappingSummary = $map.mappingSummary
}
$jsText = 'window.FIGMA_SPEC = ' + ($spec | ConvertTo-Json -Depth 16 -Compress) + ';' + $nl
[IO.File]::WriteAllText((Join-Path $here 'Preview\preview-data.js'), $jsText, $enc)
"Figma Specification: components.md ($(@($comp.components).Count) components), component-properties.md, typography-styles.md ($(@($map.textStyles).Count) styles), preview-data.js ($([math]::Round($jsText.Length / 1KB)) KB)."
